arguments.content:
*, *::before, *::after { box-sizing: border-box; }

body {
  margin: 0;
  padding: 2.5rem 1.25rem;
  font: 16px/1.5 system-ui, sans-serif;
  background: #f7f7f8;
  color: #1a1a1e;
}

h1 { margin: 0 0 1.25rem; font-size: 1.5rem; }

#todo-form { display: flex; gap: .5rem; margin-bottom: 1.25rem; }

#todo-input {
  flex: 1;
  padding: .6rem .75rem;
  border: 1px solid #c9c9d1;
  border-radius: 6px;
  font: inherit;
}

#todo-form button {
  padding: .6rem 1rem;
  border: 0;
  border-radius: 6px;
  background: #1a1a1e;
  color: #fff;
  font: inherit;
  cursor: pointer;
}

#todo-list { list-style: none; margin: 0; padding: 0; }

#todo-list li {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .6rem .75rem;
  background: #fff;
  border: 1px solid #e4e4ea;
  border-radius: 6px;
  margin-bottom: .5rem;
}

#todo-list li.done span { text-decoration: line-through; color: #8b8b96; }
#todo-list li span { flex: 1; }

const STORAGE_KEY = 'rijo-e2e-todos';

const form = document.getElementById('todo-form');
const input = document.getElementById('todo-input');
const list = document.getElementById('todo-list');

let todos = load();

function load() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
  } catch (err) {
    return [];
  }
}

function save() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
}

function render() {
  list.textContent = '';
  todos.forEach(function (todo, index) {
    const item = document.createElement('li');
    if (todo.done) item.classList.add('done');

    const box = document.createElement('input');
    box.type = 'checkbox';
    box.checked = todo.done;
    box.addEventListener('change', function () {
      todos[index].done = box.checked;
      save();
      render();
    });

    const label = document.createElement('span');
    label.textContent = todo.text;

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.textContent = 'Löschen';
    remove.addEventListener('click', function () {
      todos.splice(index, 1);
      save();
      render();
    });

    item.append(box, label, remove);
    list.append(item);
  });
}

form.addEventListener('submit', function (event) {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) return;
  todos.push({ text: text, done: false });
  input.value = '';
  save();
  render();
});

render();
